test("T-US02-06: loading blocks progression and a late response cannot replace the Back route", async ({
  page,
}) => {
  let releaseResponse!: () => void;
  let signalRequestStarted!: () => void;
  const responseGate = new Promise<void>((resolve) => {
    releaseResponse = resolve;
  });
  const requestStarted = new Promise<void>((resolve) => {
    signalRequestStarted = resolve;
  });
  await page.route("**/api/quote-content/v1/co/plans", async (route) => {
    signalRequestStarted();
    await responseGate;
    try {
      await route.fulfill({
        status: 200,
        json: {
          schemaVersion: 1,
          country: "co",
          plans: [
            {
              id: "late-plan",
              name: "Late plan",
              shortDescription: "Stale response",
              basePrice: { amountMinor: 10000, currency: "COP" },
              coverages: [],
              benefits: [],
              order: 1,
              recommended: false,
            },
          ],
        },
      });
    } catch {
      // The request can be cancelled when Back leaves the plans route.
    }
  });

  await completeDetails(page, "co");
  await requestStarted;
  await expect(
    page.getByText("Cargando los planes…", { exact: true }),
  ).toBeVisible();
  await expect(page.getByRole("button", { name: "Continuar" })).toHaveCount(0);
  const backNavigation = page
    .getByRole("link", { name: "Volver a datos" })
    .click();
  releaseResponse();
  await backNavigation;
  await expect(page).toHaveURL(/\/co\/quote\/details$/);
  await expect(
    page.getByRole("heading", { name: "Datos para cotizar" }),
  ).toBeVisible();
  await expect(page.getByText("Late plan")).toHaveCount(0);
});

test("T-US02-07: forced-colors emulation preserves the native checked radio", async ({
  page,
}, testInfo) => {
  await page.emulateMedia({ forcedColors: "active" });
  await page.setViewportSize({ width: 1280, height: 900 });
  await completeDetails(page, "co");

  const radio = page.getByRole("radio", { name: "Esencial", exact: true });
  await expect(radio).toBeVisible();
  expect(
    await page.evaluate(() => matchMedia("(forced-colors: active)").matches),
  ).toBe(true);
  await radio.focus();
  await page.keyboard.press("Space");
  await expect(radio).toBeChecked();

  const radioStyle = await radio.evaluate((element) => {
    const style = getComputedStyle(element);
    return {
      appearance: style.appearance,
      visibility: style.visibility,
      opacity: style.opacity,
      forcedColorAdjust: style.forcedColorAdjust,
    };
  });
  expect(radioStyle.appearance).not.toBe("none");
  expect(radioStyle.visibility).toBe("visible");
  expect(radioStyle.opacity).not.toBe("0");
  await page.screenshot({
    path: testInfo.outputPath("forced-colors.png"),
    fullPage: true,
  });
});
@let state = view();
@let choice = selected();
<div class="mx-auto max-w-[58rem]">
  <h1 #heading id="screen-heading" tabindex="-1" class="mt-6 mb-5 lg:my-8 lg:text-center">
    Elige tu plan
  </h1>
  <div
    role="status"
    class="text-sm text-secondary"
    [class.mb-4]="
      status() && ((state.phase === 'ready' && state.lostChoice) || state.phase === 'checking')
    "
    [class.sr-only]="
      state.phase === 'unavailable' || (state.phase === 'ready' && !state.lostChoice)
    "
  >
    {{ status() }}
  </div>

  @if (state.phase === 'ready' && state.plans.length) {
    <fieldset class="min-w-0">
      <legend class="mb-3 text-sm font-bold">Planes disponibles</legend>
      <div class="grid grid-cols-[repeat(auto-fit,minmax(min(100%,16rem),1fr))] gap-6">
        @for (plan of state.plans; track plan.id) {
          @let checked = plan.id === choice?.id;
          <article
            class="relative isolate min-w-0 rounded-lg border px-4 pt-1 pb-5 wrap-anywhere"
            [class]="
              checked ? 'border-link bg-context ring-1 ring-link' : 'border-control bg-paper'
            "
          >
            <div class="flex flex-wrap items-center justify-between gap-x-2">
              <div class="flex min-w-0 items-center gap-2">
                <input
                  type="radio"
                  name="quote-plan"
                  class="relative z-10 size-5 shrink-0 cursor-pointer accent-link"
                  [id]="'plan-' + plan.id"
                  [attr.aria-describedby]="
                    'price-' + plan.id + (plan.recommended ? ' recommended-' + plan.id : '')
                  "
                  [checked]="checked"
                  (change)="store.choose(country(), plan.id)"
                />
                <label
                  class="inline-flex min-h-11 min-w-0 items-center font-heading text-2xl after:absolute after:-inset-px after:cursor-pointer after:rounded-lg"
                  [attr.for]="'plan-' + plan.id"
                  >{{ plan.name }}</label
                >
              </div>
              @if (plan.recommended) {
                <span
                  [id]="'recommended-' + plan.id"
                  class="rounded-sm bg-link px-2 py-1 text-xs font-bold text-white"
                >
                  Recomendado
                </span>
              }
            </div>
            <p [id]="'price-' + plan.id" class="text-2xl font-bold text-link sm:text-[1.75rem]">
              {{ displayPrice(plan.basePrice) }}
            </p>
            <p class="mt-1 text-secondary">{{ plan.shortDescription }}</p>
            @if (plan.coverages.length || plan.benefits.length) {
              <div class="mt-3 space-y-3 border-t border-divider pt-3">
                @if (plan.coverages.length) {
                  <div>
                    <h2 class="font-interface text-sm font-bold">Coberturas</h2>
                    <ul class="mt-1 list-disc space-y-1 ps-4 text-sm text-secondary">
                      @for (coverage of plan.coverages; track $index) {
                        <li>{{ coverage }}</li>
                      }
                    </ul>
                  </div>
                }
                @if (plan.benefits.length) {
                  <div>
                    <h2 class="font-interface text-sm font-bold">Beneficios</h2>
                    <ul class="mt-1 list-disc space-y-1 ps-4 text-sm text-secondary">
                      @for (benefit of plan.benefits; track $index) {
                        <li>{{ benefit }}</li>
                      }
                    </ul>
                  </div>
                }
              </div>
            }
          </article>
        }
      </div>
    </fieldset>
  } @else if (state.phase === 'ready') {
    <section class="rounded-lg border border-divider bg-paper px-4 py-5 sm:px-6">
      <h2>No hay planes disponibles</h2>
      <p class="mt-2 text-sm text-secondary">Por ahora no hay planes para {{ countryLabel() }}.</p>
    </section>
  } @else if (state.phase === 'unavailable' || state.phase === 'retrying') {
    <section
      class="rounded-lg border px-4 py-5 sm:px-6"
      [class]="
        state.phase === 'unavailable'
          ? 'border-error bg-error-tint text-error'
          : 'border-divider bg-paper'
      "
    >
      @if (state.phase === 'unavailable') {
        <h2>Planes no disponibles</h2>
        <p class="mt-2 text-sm">No pudimos cargar los planes. Intenta de nuevo.</p>
      }
      <button
        type="button"
        class="primary-button mt-4 inline-flex min-h-12 items-center justify-center rounded-md bg-action px-6 font-bold text-white hover:bg-action-hover aria-disabled:opacity-60"
        [attr.aria-disabled]="state.phase === 'retrying' ? 'true' : null"
        (click)="retry($event)"
      >
        Reintentar
      </button>
    </section>
  } @else if (state.phase === 'loading') {
    <div
      class="mt-3 rounded-lg border border-divider bg-paper px-4 py-5 sm:px-6"
      aria-hidden="true"
    >
      <div class="h-3 rounded bg-context"></div>
      <div class="mt-2 h-3 w-3/5 rounded bg-context"></div>
    </div>
  }

  <div class="mt-4 flex flex-col gap-2 md:flex-row md:items-start md:justify-between">
    <a
      class="inline-flex min-h-12 self-start items-center font-bold text-link underline underline-offset-4"
      [routerLink]="['/', country(), 'quote', 'details']"
      >Volver a datos</a
    >
    @if (state.phase === 'ready' && state.plans.length) {
      <div class="flex flex-col gap-2 md:items-end">
        @if (!choice) {
          <p id="plan-action-help" class="text-sm text-secondary">
            Selecciona un plan para continuar
          </p>
        }
        <button
          type="button"
          class="primary-button min-h-12 rounded-md bg-action px-6 font-bold text-white enabled:hover:bg-action-hover disabled:bg-divider disabled:text-muted md:min-w-40"
          [disabled]="!choice"
          [attr.aria-describedby]="choice ? null : 'plan-action-help'"
          (click)="proceed()"
        >
          Continuar
        </button>
      </div>
    }
  </div>
</div>
import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  Injector,
  input,
  output,
  viewChild,
  type ElementRef,
} from '@angular/core';
import { RouterLink } from '@angular/router';
import type { Country } from '@quote/contract';
import { PlanState } from './plan-state';

import { displayPrice } from './price-format';

@Component({
  selector: 'app-plan-list',
  imports: [RouterLink],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './plan-list.html',
})
export class PlanList {
  readonly country = input.required<Country>();
  readonly complete = output<void>();
  protected readonly store = inject(PlanState);
  private readonly injector = inject(Injector);
  private readonly heading = viewChild.required<ElementRef<HTMLElement>>('heading');
  private retryHadFocus = false;
  protected readonly view = computed(() => {
    const state = this.store.view();
    return state.phase !== 'idle' && state.country === this.country()
      ? state
      : { phase: 'loading' as const };
  });
  protected readonly selected = computed(() => this.store.selected(this.country()));
  protected readonly countryLabel = computed(() =>
    this.country() === 'co' ? 'Colombia' : 'Chile',
  );
  protected readonly status = computed(() => {
    const state = this.view();
    switch (state.phase) {
      case 'loading':
      case 'retrying':
        return 'Cargando los planes…';
      case 'checking':
        return 'Verificando tu plan…';
      case 'unavailable':
        return 'No pudimos cargar los planes. Intenta de nuevo.';
      case 'ready':
        if (state.lostChoice)
          return state.plans.length
            ? 'Tu plan cambió o ya no está disponible. Selecciona un plan para continuar.'
            : 'Tu plan cambió o ya no está disponible.';
        if (!state.plans.length) return 'No hay planes disponibles.';
        return state.recovered ? 'Planes disponibles.' : '';
    }
  });

  constructor() {
    effect(() => {
      this.country();
      this.focusHeading();
    });

    effect(() => {
      const state = this.view();
      if (state.phase === 'retrying') return;
      if (state.phase === 'ready' && state.recovered && this.retryHadFocus) {
        afterNextRender(
          () => {
            const focused = document.activeElement;
            if (focused === document.body) this.heading().nativeElement.focus();
          },
          { injector: this.injector },
        );
      }
      this.retryHadFocus = false;
    });
  }

  protected retry(event: MouseEvent) {
    if (this.view().phase !== 'unavailable') return;
    this.retryHadFocus = document.activeElement === event.currentTarget;
    this.store.read(this.country(), 'retrying');
  }

  protected proceed() {
    if (!this.selected()) return;
    this.heading().nativeElement.focus();
    this.complete.emit();
  }

  protected readonly displayPrice = displayPrice;

  private focusHeading() {
    afterNextRender(() => this.heading().nativeElement.focus(), { injector: this.injector });
  }
}
