import { expect, test } from "@playwright/test";

test("US-01 T-US01-01/03/07/10/11/13: navigate, validate and recover a country draft", async ({
  page,
}) => {
  const writeRequests: string[] = [];
  page.on("request", (request) => {
    if (request.method() !== "GET") writeRequests.push(request.url());
  });

  await page.goto("/");
  const colombia = page.getByRole("link", { name: "Colombia", exact: true });
  await colombia.focus();
  await page.keyboard.press("Enter");
  await expect(page).toHaveURL(/\/co\/quote\/details$/);
  const name = page.getByRole("textbox", { name: "Nombre del titular" });
  await expect(name).toHaveAttribute("aria-invalid", "false");
  await page.getByRole("button", { name: "Continuar" }).click();
  await expect(name).toBeFocused();
  await expect(name).toHaveAccessibleDescription(
    "Ingresa el nombre del titular.",
  );

  await name.fill("Persona Demo");
  await expect(name).toHaveAttribute("aria-invalid", "false");
  await page
    .getByLabel("Tipo de documento")
    .selectOption({ label: "Cédula de ciudadanía" });
  await page.getByLabel("Número de documento").fill("DEMO-ID");
  await page.getByLabel("Fecha de nacimiento").fill("1992-04-16");
  await page.getByLabel("Placa").fill("DEMO-CO");
  await page.getByLabel("Año del vehículo").fill("2021");
  await page.getByLabel("Marca").selectOption({ label: "Ejemplo Motor" });
  await page.getByRole("button", { name: "Continuar" }).click();

  await expect(page).toHaveURL(/\/co\/quote\/plans$/);
  await page.getByRole("link", { name: "Volver a datos" }).click();
  await expect(name).toHaveValue("Persona Demo");
  await page.reload();
  await expect(name).toHaveValue("Persona Demo");
  await expect(page.getByLabel("Año del vehículo")).toHaveValue("2021");

  await page.goto("/CL/quote/details");
  await expect(page).toHaveURL(/\/cl\/quote\/details$/);
  await expect(page.getByLabel("RUT")).toBeVisible();
  await expect(name).toHaveValue("");
  await expect(page.getByLabel("Número de documento")).toHaveCount(0);
  await page.setViewportSize({ width: 320, height: 740 });
  expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBe(
    320,
  );
  expect(writeRequests).toEqual([]);
});

test("US-01 T-US01-08/13: recover invalid country and configuration without stale fields", async ({
  page,
}) => {
  await page.goto("/zz/quote/details");
  await expect(page).toHaveURL(/\/zz\/quote\/details$/);
  await expect(page.getByText("Este país no está disponible.")).toBeVisible();

  await page.route(
    "**/api/quote-content/v1/cl/form",
    (route) =>
      route.fulfill({
        status: 503,
        json: { error: { code: "FORM_UNAVAILABLE" } },
      }),
    { times: 1 },
  );
reviews/US-01-review.md:92:- **Non-blocking QA limits:** The QA report records one unrelated US-02 keyboard-focus failure in the fresh 35-test browser suite and two existing-volume US-01 tests whose hard-coded default make option did not match the edited live catalog. The relevant US-01 and US-03 browser cases passed on the fresh stack; the existing-volume Chrome smoke check confirmed both country forms. The orchestrator did not capture a pre-migration snapshot of the existing database, so exact existing-volume preservation is supported by the isolated migration regression and by the migration's scoped component update, not a live before/after content comparison. QA also verified both named volumes remained present and no database/volume was deleted. These limits are accurately disclosed and do not indicate a field-removal defect.
FLOW.md:405:- The orchestrator started fresh isolated Compose with `docker compose -p accessory-field-fresh up -d --build --wait`. It became healthy; QA observed HTTP 200 form reads with 7 CO fields and 6 CL fields, neither containing the retired field. QA's Chrome full suite passed 34/35: all US-01 and US-03 cases passed; one unrelated US-02 keyboard-focus assertion failed. The orchestrator stopped only these containers with `docker compose -p accessory-field-fresh stop`, without removing the fresh volume.
FLOW.md:407:- The orchestrator delegated independent QA to `/root/field_removal_qa`, configured `gpt-6-luna` / `xhigh`. QA used `test-driven-development`, reran `CI=1 pnpm test`, `pnpm test:content`, CMS typecheck, lint, and `pnpm format:check`; all passed. Its focused existing-volume browser run passed 11/13: two US-01 tests expect the default `Ejemplo Motor` make option, whereas that existing catalog retains edited Mazda/Chevrolet options. The five US-03 terminal cases and the generic checkbox-removal reconciliation case passed. QA documented these unrelated test limitations and the absence of a live pre-migration snapshot in [the US-01 QA report](reports/qa/US-01-qa-report.md).
FLOW.md:414:- The approval accepts the three documented unrelated browser failures and the absence of a live before/after snapshot of the existing database. The fresh full browser run remains **34/35** and the existing-volume focused run remains **11/13**; neither is marked as passing. The isolated Strapi migration regression remains the evidence for preservation of divergent published and draft content. The existing database and both Compose volumes remain present.
